//! Layouts (INS §5.21, ADR 0033): a separate artefact that cuts one instrument's ordered
//! elements into steps, tabs, cards and rows, and chooses presentations. A layout never
//! changes content and never permutes it (INS-203, INS-214).
//!
//! A [`Layout`] is constructed only by `ValidateLayout`
//! ([`validate_layout`](crate::application::validate_layout)), which checks it against the
//! instrument it is bound to, or generated by [`default_layout`](crate::application::default_layout)
//! (INS-206).

use std::collections::BTreeMap;

use fieldseal_kernel::Value;
use fieldseal_kernel::id::Fingerprint;

use super::text::LocalisedText;
use super::version::{SchemaRange, SemVer};

/// The window class a layout targets (INS-207), by available width in density-independent
/// pixels.
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug)]
pub enum WindowClass {
    /// Below 600.
    Compact,
    /// 600 to 839.
    Medium,
    /// 840 or more.
    Expanded,
}

impl WindowClass {
    /// Every class, smallest first.
    pub const ALL: [WindowClass; 3] = [WindowClass::Compact, WindowClass::Medium, WindowClass::Expanded];

    /// The class's name in documents and plans.
    pub fn name(self) -> &'static str {
        match self {
            WindowClass::Compact => "compact",
            WindowClass::Medium => "medium",
            WindowClass::Expanded => "expanded",
        }
    }

    /// The class named `name`.
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|c| c.name() == name)
    }

    /// The class of a window `width` density-independent pixels wide (INS-207).
    pub fn for_width(width: u32) -> Self {
        match width {
            0..600 => WindowClass::Compact,
            600..840 => WindowClass::Medium,
            _ => WindowClass::Expanded,
        }
    }
}

/// How the collector moves between steps (INS-205).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Navigation {
    /// Steps are visited in order; the collector may go back.
    Linear,
    /// Any step may be visited.
    Free,
}

impl Navigation {
    /// The name in documents and plans.
    pub fn name(self) -> &'static str {
        match self {
            Navigation::Linear => "linear",
            Navigation::Free => "free",
        }
    }
}

/// A container's density (INS-204).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Emphasis {
    /// The platform's usual spacing.
    Normal,
    /// Tighter spacing.
    Compact,
}

impl Emphasis {
    /// The name in documents and plans.
    pub fn name(self) -> &'static str {
        match self {
            Emphasis::Normal => "normal",
            Emphasis::Compact => "compact",
        }
    }
}

/// How a repeat group is drawn (INS-201).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum RepeatAs {
    /// Instances as rows, children as columns: the paper grid.
    Table,
    /// One card per instance: item by item.
    List,
}

impl RepeatAs {
    /// The name in documents and plans.
    pub fn name(self) -> &'static str {
        match self {
            RepeatAs::Table => "table",
            RepeatAs::List => "list",
        }
    }
}

/// A presentation a control allows (INS-204, §5.3).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Presentation {
    /// `scale`: a slider.
    Slider,
    /// `scale`: segmented buttons.
    Segments,
    /// `yes-no`: a switch.
    Switch,
    /// `yes-no`: two buttons.
    Buttons,
    /// `money`: a stepper on a grid of `step`.
    Stepper,
    /// `money`: typed entry.
    Entry,
}

impl Presentation {
    /// Every presentation.
    pub const ALL: [Presentation; 6] =
        [Presentation::Slider, Presentation::Segments, Presentation::Switch, Presentation::Buttons, Presentation::Stepper, Presentation::Entry];

    /// The name in documents and plans.
    pub fn name(self) -> &'static str {
        match self {
            Presentation::Slider => "slider",
            Presentation::Segments => "segments",
            Presentation::Switch => "switch",
            Presentation::Buttons => "buttons",
            Presentation::Stepper => "stepper",
            Presentation::Entry => "entry",
        }
    }

    /// The presentation named `name`.
    pub fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|p| p.name() == name)
    }
}

/// How a layout names its instrument (INS-200).
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum InstrumentReference {
    /// The authoring form: a source path, replaced by the fingerprint when canonicalised.
    Source(String),
    /// The canonical form: the instrument's salted fingerprint (WIRE-186).
    Fingerprint(Fingerprint),
}

/// One leaf or container in a layout.
#[derive(Clone, PartialEq, Eq, Debug)]
pub enum Content {
    /// `{element: <path>}`: one question or display element (INS-201), with an optional
    /// presentation (INS-204).
    Element {
        /// The element's full path.
        path: String,
        /// The presentation chosen for a question's control.
        presentation: Option<Presentation>,
        /// Where it was authored.
        doc_path: String,
    },
    /// `{group: <path>}`: a group, laid out as the default layout lays out its subtree.
    Group {
        /// The group's full path.
        path: String,
        /// Where it was authored.
        doc_path: String,
    },
    /// `{repeat: <path>, as: table | list}`: a repeat group.
    Repeat {
        /// The repeat group's full path.
        path: String,
        /// How it is drawn.
        repeat_as: RepeatAs,
        /// Where it was authored.
        doc_path: String,
    },
    /// `tabs: [{tab: …}]`: sibling groups the collector moves between freely (INS-215).
    Tabs {
        /// The tabs, in order.
        tabs: Vec<Container>,
        /// Where it was authored.
        doc_path: String,
    },
    /// `card: {…}`: a visually bounded group.
    Card(Container),
    /// `row: {…}`: controls side by side on wide screens.
    Row(Container),
}

impl Content {
    /// Where it was authored.
    pub fn doc_path(&self) -> &str {
        match self {
            Content::Element { doc_path, .. } | Content::Group { doc_path, .. } | Content::Repeat { doc_path, .. } | Content::Tabs { doc_path, .. } => doc_path,
            Content::Card(c) | Content::Row(c) => &c.doc_path,
        }
    }
}

/// A `tab`, `card` or `row`: optional heading, icon and emphasis, and its contents.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Container {
    /// The localised heading (required for a tab, absent for a row).
    pub title: Option<LocalisedText>,
    /// A single emoji (INS-183).
    pub icon: Option<String>,
    /// The density.
    pub emphasis: Option<Emphasis>,
    /// What it holds, in order.
    pub contents: Vec<Content>,
    /// Where it was authored.
    pub doc_path: String,
}

/// One `step` of navigation.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct LayoutStep {
    /// Its localised title.
    pub title: LocalisedText,
    /// How the collector reaches it (INS-205).
    pub navigation: Navigation,
    /// The density.
    pub emphasis: Option<Emphasis>,
    /// What it holds, in order.
    pub contents: Vec<Content>,
    /// Where it was authored.
    pub doc_path: String,
}

/// A validated layout (INS-200), or the generated default layout (INS-206).
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Layout {
    pub(crate) name: String,
    pub(crate) version: SemVer,
    pub(crate) schema: SchemaRange,
    pub(crate) instrument: InstrumentReference,
    pub(crate) window_class: Option<WindowClass>,
    pub(crate) steps: Vec<LayoutStep>,
    /// The fingerprint validation bound it to, if a binding was supplied.
    pub(crate) bound: Option<Fingerprint>,
    /// The question paths of the instrument it was validated against, in tree order.
    pub(crate) questions: Vec<String>,
    /// Whether this is the generated default layout (INS-206).
    pub(crate) is_default: bool,
}

impl Layout {
    /// `metadata.name`: a label.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// `metadata.version`: a label.
    pub fn version(&self) -> &SemVer {
        &self.version
    }

    /// `spec.schema` (INS-091).
    pub fn schema(&self) -> SchemaRange {
        self.schema
    }

    /// `spec.instrument` as authored.
    pub fn instrument(&self) -> &InstrumentReference {
        &self.instrument
    }

    /// The fingerprint the layout was bound to by validation, if known.
    pub fn bound_fingerprint(&self) -> Option<&Fingerprint> {
        self.bound.as_ref()
    }

    /// `spec.windowClass` (INS-207).
    pub fn window_class(&self) -> Option<WindowClass> {
        self.window_class
    }

    /// The steps, in order.
    pub fn steps(&self) -> &[LayoutStep] {
        &self.steps
    }

    /// Whether this is the generated default layout (INS-206). Records collected with it
    /// name `"default"` instead of a content address (INS-209).
    pub fn is_default(&self) -> bool {
        self.is_default
    }

    /// The canonical value tree of the layout (INS-200, WIRE §canonical-encoding): the
    /// document as validated, with `spec.instrument` replaced by the bound fingerprint (a
    /// 32-byte string, WIRE-186) when validation was given one. The format core encodes it and
    /// computes the layout's content address; this context doesn't hash.
    pub fn to_value(&self) -> Value {
        let mut spec = BTreeMap::new();
        spec.insert("schema".to_owned(), Value::Text(self.schema.to_string()));
        let instrument = match (&self.bound, &self.instrument) {
            (Some(fp), _) | (None, InstrumentReference::Fingerprint(fp)) => Value::Bytes(fp.as_bytes().to_vec()),
            (None, InstrumentReference::Source(s)) => Value::Text(s.clone()),
        };
        spec.insert("instrument".to_owned(), instrument);
        if let Some(c) = self.window_class {
            spec.insert("windowClass".to_owned(), Value::Text(c.name().to_owned()));
        }
        spec.insert("steps".to_owned(), Value::Array(self.steps.iter().map(step_value).collect()));
        let mut metadata = BTreeMap::new();
        metadata.insert("name".to_owned(), Value::Text(self.name.clone()));
        metadata.insert("version".to_owned(), Value::Text(self.version.to_string()));
        let mut top = BTreeMap::new();
        top.insert("apiVersion".to_owned(), Value::Text("fieldseal.dev/v1alpha1".to_owned()));
        top.insert("kind".to_owned(), Value::Text("Layout".to_owned()));
        top.insert("metadata".to_owned(), Value::Map(metadata));
        top.insert("spec".to_owned(), Value::Map(spec));
        Value::Map(top)
    }
}

fn text(s: &str) -> Value {
    Value::Text(s.to_owned())
}

fn step_value(s: &LayoutStep) -> Value {
    let mut m = BTreeMap::new();
    m.insert("title".to_owned(), s.title.to_value());
    m.insert("navigation".to_owned(), text(s.navigation.name()));
    if let Some(e) = s.emphasis {
        m.insert("emphasis".to_owned(), text(e.name()));
    }
    m.insert("contents".to_owned(), Value::Array(s.contents.iter().map(content_value).collect()));
    Value::Map(m)
}

fn container_value(c: &Container) -> Value {
    let mut m = BTreeMap::new();
    if let Some(t) = &c.title {
        m.insert("title".to_owned(), t.to_value());
    }
    if let Some(i) = &c.icon {
        m.insert("icon".to_owned(), text(i));
    }
    if let Some(e) = c.emphasis {
        m.insert("emphasis".to_owned(), text(e.name()));
    }
    m.insert("contents".to_owned(), Value::Array(c.contents.iter().map(content_value).collect()));
    Value::Map(m)
}

fn single(key: &str, v: Value) -> Value {
    let mut m = BTreeMap::new();
    m.insert(key.to_owned(), v);
    Value::Map(m)
}

fn content_value(c: &Content) -> Value {
    match c {
        Content::Element { path, presentation, .. } => {
            let mut m = BTreeMap::new();
            m.insert("element".to_owned(), text(path));
            if let Some(p) = presentation {
                m.insert("presentation".to_owned(), text(p.name()));
            }
            Value::Map(m)
        }
        Content::Group { path, .. } => single("group", text(path)),
        Content::Repeat { path, repeat_as, .. } => {
            let mut m = BTreeMap::new();
            m.insert("repeat".to_owned(), text(path));
            m.insert("as".to_owned(), text(repeat_as.name()));
            Value::Map(m)
        }
        Content::Tabs { tabs, .. } => single("tabs", Value::Array(tabs.iter().map(|t| single("tab", container_value(t))).collect())),
        Content::Card(c) => single("card", container_value(c)),
        Content::Row(c) => single("row", container_value(c)),
    }
}
